<?php require_once 'functions.php'; require_login(); $errors=[]; $types=['lost','found']; $categories=['Electronics','Wallets & IDs','Keys','Bags','Clothing','Jewelry','Documents','Accessories','Other'];
if($_SERVER['REQUEST_METHOD']==='POST'){$type=$_POST['item_type']??'';$title=trim($_POST['title']??'');$category=$_POST['category']??'Other';$place=trim($_POST['place']??'');$date=$_POST['item_date']??'';$description=trim($_POST['description']??'');$contact=trim($_POST['contact_info']??'');$photo=null;
if(!in_array($type,$types,true))$errors[]='Choose lost or found.';if($title===''||$place===''||$date===''||$contact==='')$errors[]='Complete all required fields.';if(!in_array($category,$categories,true))$category='Other';if($date!==''&&strtotime($date)>time())$errors[]='Date cannot be in the future.';
if(isset($_FILES['photo'])&&$_FILES['photo']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['photo'];$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$mime='';if($f['error']!==UPLOAD_ERR_OK)$errors[]='Photo upload failed.';elseif($f['size']>3*1024*1024)$errors[]='Photo must be 3 MB or smaller.';else{$fi=new finfo(FILEINFO_MIME_TYPE);$mime=$fi->file($f['tmp_name']);if(!isset($allowed[$mime]))$errors[]='Photo must be JPG, PNG, or WEBP.';else{$photo='uploads/'.bin2hex(random_bytes(12)).'.'.$allowed[$mime];}}}
if(!$errors){if($photo&& !move_uploaded_file($_FILES['photo']['tmp_name'],__DIR__.'/'.$photo)){$errors[]='Could not save uploaded photo.';}else{$st=$pdo->prepare('INSERT INTO items(user_id,item_type,title,category,place,item_date,description,contact_info,photo_path) VALUES(?,?,?,?,?,?,?,?,?)');$st->execute([$_SESSION['user']['id'],$type,$title,$category,$place,$date,$description,$contact,$photo]);flash('Your item report has been posted.');header('Location: item.php?id='.$pdo->lastInsertId());exit;}}}
page_header('Report an item'); ?><div class="form-layout"><div><p class="eyebrow">HELP THE COMMUNITY</p><h1>Report an item</h1><p class="muted">Share clear details so the right person can recognize the item. Please avoid posting sensitive personal information.</p><div class="tip-box"><strong>Helpful tips</strong><ul><li>Use a clear item title.</li><li>Add the location and date.</li><li>Describe unique features.</li><li>Only share contact details you are comfortable making public.</li></ul></div></div><form class="panel report-form" method="post" enctype="multipart/form-data"><?php foreach($errors as $err): ?><div class="alert error"><?=e($err)?></div><?php endforeach; ?><label>Report type *<select name="item_type" required><option value="">Choose type</option><option value="lost" <?=($_POST['item_type']??'')==='lost'?'selected':''?>>I lost an item</option><option value="found" <?=($_POST['item_type']??'')==='found'?'selected':''?>>I found an item</option></select></label><label>Item name *<input name="title" maxlength="160" required placeholder="e.g. Black wallet" value="<?=e($_POST['title']??'')?>"></label><label>Category *<select name="category"><?php foreach($categories as $c): ?><option <?=($_POST['category']??'')===$c?'selected':''?>><?=e($c)?></option><?php endforeach; ?></select></label><div class="two-col"><label>Location *<input name="place" required maxlength="255" placeholder="Where was it lost/found?" value="<?=e($_POST['place']??'')?>"></label><label>Date *<input type="date" name="item_date" max="<?=date('Y-m-d')?>" required value="<?=e($_POST['item_date']??date('Y-m-d'))?>"></label></div><label>Description<textarea name="description" rows="4" placeholder="Color, brand, identifying details…"><?=e($_POST['description']??'')?></textarea></label><label>Contact information *<input name="contact_info" required maxlength="255" placeholder="Email, phone, or preferred contact" value="<?=e($_POST['contact_info']??'')?>"></label><label>Photo (optional, JPG/PNG/WEBP, max 3 MB)<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></label><button class="button full" type="submit">Publish report</button></form></div><?php page_footer(); ?>
